sql.where:
i.is_deleted = false AND i.deleted_at IS NULL AND id.deleted_at IS NULL AND s.is_deleted = false AND s.deleted_at IS NULL
AND i.status = 1
AND i.shop_id = #{currentUserShopId}
AND i.shop_id = #{shopId}
AND i.invoice_id = #{invoiceId}::uuid
AND i.created_at >= #{startDateTime}
AND i.created_at <= #{endDateTime}
AND ( d.drink_name ILIKE '%' || #{search} || '%' OR p.full_name ILIKE '%' || #{search} || '%' OR s.shop_name ILIKE '%' || #{search} || '%' OR CAST(st.table_number AS VARCHAR) ILIKE '%' || #{search} || '%' OR CAST(i.invoice_id AS VARCHAR) ILIKE '%' || #{search} || '%' OR i.invoice_code ILIKE '%' || #{search} || '%' )
